import {
    _decorator, Component, Node, Canvas, UITransform, Widget, Sprite, Label, Color,
    SpriteFrame, ImageAsset, Texture2D, Layout, Button, EventTouch, view, Vec3, UIOpacity, Camera,
} from 'cc';
import { EventBus, GameEvents } from '../core/EventBus';
import { PlayerStats } from '../player/PlayerStats';
import { Inventory } from '../inventory/Inventory';
import { ItemDB, RarityColor, EquipSlot } from '../inventory/Items';
import { PlayerCombat, SkillDef } from '../player/PlayerCombat';
import { QuestManager } from '../quest/QuestManager';
import { NPCDefs } from '../npc/NPC';

const { ccclass } = _decorator;

// ---------- helpers to build a 1x1 solid-color sprite frame ----------
const sfCache: Map<string, SpriteFrame> = new Map();
function solidSpriteFrame(color: Color): SpriteFrame {
    const key = `${color.r}_${color.g}_${color.b}_${color.a}`;
    if (sfCache.has(key)) return sfCache.get(key)!;
    const img = new ImageAsset({ width: 2, height: 2, _data: new Uint8Array([
        color.r, color.g, color.b, color.a, color.r, color.g, color.b, color.a,
        color.r, color.g, color.b, color.a, color.r, color.g, color.b, color.a,
    ]), _compressed: false, format: Texture2D.PixelFormat.RGBA8888 });
    const tex = new Texture2D();
    tex.image = img;
    const sf = new SpriteFrame();
    sf.texture = tex;
    // Prevent DynamicAtlasManager from trying to pack this programmatic frame.
    // The atlas calls texSubImage2D expecting an HTMLImageElement/ImageBitmap, but
    // Uint8Array-backed ImageAssets are not a valid overload → "Overload resolution failed".
    sf.packable = false;
    sfCache.set(key, sf);
    return sf;
}

function makePanel(name: string, w: number, h: number, color: Color): Node {
    const n = new Node(name);
    const ut = n.addComponent(UITransform);
    ut.setContentSize(w, h);
    const sp = n.addComponent(Sprite);
    sp.type = Sprite.Type.SIMPLE;
    sp.spriteFrame = solidSpriteFrame(color);
    return n;
}
function makeLabel(text: string, size = 16, color = new Color(255, 255, 255)): Node {
    const n = new Node('Label');
    n.addComponent(UITransform);
    const l = n.addComponent(Label);
    l.string = text;
    l.fontSize = size;
    l.lineHeight = Math.floor(size * 1.2);
    l.color = color;
    l.cacheMode = Label.CacheMode.NONE;
    return n;
}
function makeButton(label: string, w: number, h: number, color: Color, onClick: () => void): Node {
    const root = makePanel('Button', w, h, color);
    const lbl = makeLabel(label, 14);
    lbl.parent = root;
    const btn = root.addComponent(Button);
    btn.transition = Button.Transition.SCALE;
    btn.zoomScale = 0.95;
    root.on(Node.EventType.TOUCH_END, onClick);
    return root;
}

function anchorTopLeft(node: Node, l: number, t: number) {
    const w = node.addComponent(Widget);
    w.isAlignLeft = true; w.left = l;
    w.isAlignTop = true; w.top = t;
}
function anchorTopRight(node: Node, r: number, t: number) {
    const w = node.addComponent(Widget);
    w.isAlignRight = true; w.right = r;
    w.isAlignTop = true; w.top = t;
}
function anchorBottomCenter(node: Node, b: number) {
    const w = node.addComponent(Widget);
    w.isAlignBottom = true; w.bottom = b;
    w.isAlignHorizontalCenter = true; w.horizontalCenter = 0;
}
function anchorCenter(node: Node) {
    const w = node.addComponent(Widget);
    w.isAlignHorizontalCenter = true; w.horizontalCenter = 0;
    w.isAlignVerticalCenter = true; w.verticalCenter = 0;
}

interface BarRefs { fill: Node; label: Label; bgWidth: number; }

@ccclass('UIManager')
export class UIManager extends Component {
    public stats: PlayerStats | null = null;
    public inventory: Inventory | null = null;
    public combat: PlayerCombat | null = null;
    public quests: QuestManager | null = null;

    private canvasNode!: Node;

    // HUD references
    private hpBar!: BarRefs;
    private mpBar!: BarRefs;
    private stBar!: BarRefs;
    private xpBar!: BarRefs;
    private levelLabel!: Label;
    private goldLabel!: Label;
    private skillButtons: { fill: Node, cd: Label, root: Node }[] = [];
    private notifContainer!: Node;
    private interactHint!: Node;
    private bossBar: { panel: Node, fill: Node, label: Label } | null = null;
    private damagePop!: Node;

    // Panels
    private inventoryPanel!: Node;
    private questPanel!: Node;
    private dialogPanel!: Node;

    onLoad() {
        this.setupCanvas();
        this.buildHUD();
        this.buildSkillBar();
        this.buildBossBar();
        this.buildInventoryPanel();
        this.buildQuestPanel();
        this.buildDialogPanel();
        this.buildHelpHint();

        this.bindEvents();
    }

    private setupCanvas() {
        // Build a UI Canvas node
        const canvasNode = new Node('UICanvas');
        const ut = canvasNode.addComponent(UITransform);
        const vis = view.getVisibleSize();
        ut.setContentSize(vis.width, vis.height);
        const canvas = canvasNode.addComponent(Canvas);

        // Find or create 2D camera
        let camNode = this.node.scene?.getChildByName('UICamera') as Node | undefined;
        if (!camNode) {
            camNode = new Node('UICamera');
            const cam = camNode.addComponent(Camera);
            cam.priority = 1100;
            cam.clearFlags = Camera.ClearFlag.DEPTH_ONLY;
            cam.projection = Camera.ProjectionType.ORTHO;
            cam.visibility = 1 << 25; // UI_2D layer
            camNode.layer = 1 << 25;
            this.node.scene?.addChild(camNode);
        }
        canvas.cameraComponent = camNode.getComponent(Camera);

        // Force UI layer
        canvasNode.layer = 1 << 25;
        // Add a widget that fills screen
        const w = canvasNode.addComponent(Widget);
        w.isAlignTop = w.isAlignBottom = w.isAlignLeft = w.isAlignRight = true;
        w.top = w.bottom = w.left = w.right = 0;

        this.node.scene?.addChild(canvasNode);
        this.canvasNode = canvasNode;
    }

    private addToCanvas(n: Node) {
        // Apply UI layer recursively
        this.applyUILayer(n);
        this.canvasNode.addChild(n);
    }
    private applyUILayer(n: Node) {
        n.layer = 1 << 25;
        for (const c of n.children) this.applyUILayer(c);
    }

    // ------------- HUD -------------
    private makeBar(label: string, width: number, height: number, color: Color): { root: Node, refs: BarRefs } {
        const root = makePanel('Bar', width + 100, height + 18, new Color(0, 0, 0, 0));
        // label
        const lbl = makeLabel(label, 11);
        lbl.setPosition(-width / 2 - 50 + 30, height / 2 + 2);
        root.addChild(lbl);
        // bg
        const bg = makePanel('BarBg', width, height, new Color(20, 20, 20, 200));
        bg.setPosition(0, 0);
        root.addChild(bg);
        // border
        const border = makePanel('Border', width + 2, height + 2, new Color(80, 60, 40, 255));
        border.setPosition(0, 0);
        const inner = makePanel('Inner', width, height, new Color(20, 20, 20, 220));
        border.addChild(inner);
        // fill
        const fill = makePanel('Fill', width, height, color);
        fill.getComponent(UITransform)!.setAnchorPoint(0, 0.5);
        fill.setPosition(-width / 2, 0);
        bg.addChild(fill);
        // value text
        const val = makeLabel('100/100', 11);
        val.setPosition(0, 0);
        bg.addChild(val);

        return { root, refs: { fill, label: val.getComponent(Label)!, bgWidth: width } };
    }

    private buildHUD() {
        // Top-left: player panel
        const panel = makePanel('PlayerPanel', 280, 130, new Color(20, 15, 10, 180));
        anchorTopLeft(panel, 16, 16);
        this.addToCanvas(panel);
        // border accent
        const accent = makePanel('Accent', 280, 4, new Color(180, 140, 60));
        accent.setPosition(0, 63);
        panel.addChild(accent);

        const name = makeLabel('Sir Aldric  ⚔️', 16);
        name.setPosition(-90, 50); panel.addChild(name);

        const lvl = makeLabel('Lv. 1', 14, new Color(255, 215, 100));
        lvl.setPosition(90, 50); panel.addChild(lvl);
        this.levelLabel = lvl.getComponent(Label)!;

        const hp = this.makeBar('HP', 220, 14, new Color(220, 60, 60)); this.hpBar = hp.refs;
        hp.root.setPosition(20, 25); panel.addChild(hp.root);
        const mp = this.makeBar('MP', 220, 12, new Color(80, 140, 230)); this.mpBar = mp.refs;
        mp.root.setPosition(20, 5); panel.addChild(mp.root);
        const st = this.makeBar('ST', 220, 10, new Color(220, 210, 80)); this.stBar = st.refs;
        st.root.setPosition(20, -12); panel.addChild(st.root);
        const xp = this.makeBar('XP', 220, 8, new Color(140, 220, 140)); this.xpBar = xp.refs;
        xp.root.setPosition(20, -28); panel.addChild(xp.root);

        const gold = makeLabel('💰 50', 14, new Color(255, 215, 100));
        gold.setPosition(-100, -50); panel.addChild(gold);
        this.goldLabel = gold.getComponent(Label)!;

        // Notification stack (top right)
        const notif = new Node('Notifications');
        const nut = notif.addComponent(UITransform);
        nut.setContentSize(320, 400);
        anchorTopRight(notif, 16, 16);
        const lay = notif.addComponent(Layout);
        lay.type = Layout.Type.VERTICAL;
        lay.resizeMode = Layout.ResizeMode.CONTAINER;
        lay.spacingY = 6;
        lay.horizontalDirection = Layout.HorizontalDirection.RIGHT_TO_LEFT;
        this.addToCanvas(notif);
        this.notifContainer = notif;

        // Interact hint
        const hint = makePanel('InteractHint', 280, 36, new Color(0, 0, 0, 180));
        const hintLbl = makeLabel('[E] Interact', 14, new Color(255, 220, 130));
        hintLbl.parent = hint;
        const hw = hint.addComponent(Widget);
        hw.isAlignHorizontalCenter = true; hw.horizontalCenter = 0;
        hw.isAlignBottom = true; hw.bottom = 220;
        hint.active = false;
        this.addToCanvas(hint);
        this.interactHint = hint;
    }

    private buildSkillBar() {
        const bar = makePanel('SkillBar', 5 * 70 + 20, 80, new Color(20, 15, 10, 180));
        anchorBottomCenter(bar, 24);
        this.addToCanvas(bar);

        const skills = this.combat?.skills ?? [];
        const slots = ['J', 'Q', 'E', 'R', 'F'];
        const colors = ['#dddddd'].concat(skills.map(s => s.color));

        for (let i = 0; i < 5; i++) {
            const slotColor = i === 0 ? new Color(160, 160, 160) : hexToColor(skills[i - 1]?.color ?? '#888888');
            const slot = makePanel('Slot', 60, 60, new Color(40, 30, 20, 230));
            slot.setPosition(-2 * 70 + i * 70, 0);
            bar.addChild(slot);

            const icon = makePanel('Icon', 50, 50, slotColor);
            icon.setPosition(0, 5);
            slot.addChild(icon);

            const key = makeLabel(slots[i], 12, new Color(255, 230, 150));
            key.setPosition(0, -22);
            slot.addChild(key);

            const cdMask = makePanel('CDMask', 60, 0, new Color(0, 0, 0, 180));
            cdMask.getComponent(UITransform)!.setAnchorPoint(0.5, 0);
            cdMask.setPosition(0, -30);
            slot.addChild(cdMask);

            const cdLabel = makeLabel('', 16, new Color(255, 255, 255));
            cdLabel.setPosition(0, 5);
            slot.addChild(cdLabel);

            this.skillButtons.push({ fill: cdMask, cd: cdLabel.getComponent(Label)!, root: slot });
        }
    }

    private buildBossBar() {
        const panel = makePanel('BossBar', 500, 40, new Color(20, 10, 10, 200));
        const w = panel.addComponent(Widget);
        w.isAlignHorizontalCenter = true; w.horizontalCenter = 0;
        w.isAlignTop = true; w.top = 24;
        const lbl = makeLabel('Dark Knight', 16, new Color(255, 200, 200));
        lbl.setPosition(0, 12);
        panel.addChild(lbl);
        const bgw = 480, bgh = 14;
        const bg = makePanel('BBg', bgw, bgh, new Color(40, 0, 0, 220));
        bg.setPosition(0, -8); panel.addChild(bg);
        const fill = makePanel('BFill', bgw, bgh, new Color(200, 30, 30));
        fill.getComponent(UITransform)!.setAnchorPoint(0, 0.5);
        fill.setPosition(-bgw / 2, 0);
        bg.addChild(fill);
        panel.active = false;
        this.addToCanvas(panel);
        this.bossBar = { panel, fill, label: lbl.getComponent(Label)! };
    }

    // ------------- Inventory Panel -------------
    private buildInventoryPanel() {
        const panel = makePanel('InventoryPanel', 720, 480, new Color(25, 18, 12, 240));
        anchorCenter(panel);
        panel.active = false;
        this.addToCanvas(panel);

        // Title bar
        const titleBar = makePanel('Title', 720, 36, new Color(140, 90, 40));
        titleBar.setPosition(0, 222);
        const title = makeLabel('⚔️  Inventory & Equipment  ⚔️', 18);
        titleBar.addChild(title);
        panel.addChild(titleBar);

        // Close
        const close = makeButton('✕', 30, 28, new Color(160, 50, 50), () => { panel.active = false; });
        close.setPosition(335, 222);
        panel.addChild(close);

        // Left: Equipment slots
        const eqPanel = makePanel('Equipment', 240, 400, new Color(40, 30, 20, 220));
        eqPanel.setPosition(-220, -10);
        panel.addChild(eqPanel);

        const slots: EquipSlot[] = ['helmet', 'amulet', 'armor', 'weapon', 'ring', 'boots'];
        const slotIcons: Record<EquipSlot, string> = { helmet: '⛑️', amulet: '📿', armor: '🛡️', weapon: '⚔️', ring: '💍', boots: '🥾' };
        for (let i = 0; i < slots.length; i++) {
            const slot = slots[i];
            const cx = (i % 2 === 0 ? -50 : 50);
            const cy = 140 - Math.floor(i / 2) * 110;
            const sBg = makePanel('SlotBg', 80, 80, new Color(60, 45, 30));
            sBg.setPosition(cx, cy);
            eqPanel.addChild(sBg);
            const sLabel = makeLabel(slot.toUpperCase(), 10, new Color(220, 200, 160));
            sLabel.setPosition(0, 50);
            sBg.addChild(sLabel);
            const sIcon = makeLabel(slotIcons[slot], 32);
            sIcon.setPosition(0, 0);
            sBg.addChild(sIcon);

            // Click to unequip
            const btn = sBg.addComponent(Button);
            btn.transition = Button.Transition.SCALE;
            sBg.on(Node.EventType.TOUCH_END, () => {
                if (this.inventory?.equipment[slot]) {
                    this.inventory.unequip(slot);
                    this.refreshInventory();
                }
            });

            (sBg as any).__slotKind = slot;
            (sBg as any).__iconLabel = sIcon.getComponent(Label)!;
            (sBg as any).__nameLabel = sLabel.getComponent(Label)!;
        }

        // Right: Item grid scrollable (simple grid)
        const invPanel = makePanel('Items', 440, 400, new Color(40, 30, 20, 220));
        invPanel.setPosition(120, -10);
        panel.addChild(invPanel);
        const gridContainer = new Node('Grid');
        gridContainer.addComponent(UITransform).setContentSize(420, 380);
        const lay = gridContainer.addComponent(Layout);
        lay.type = Layout.Type.GRID;
        lay.resizeMode = Layout.ResizeMode.CONTAINER;
        lay.startAxis = Layout.AxisDirection.HORIZONTAL;
        lay.cellSize = { width: 64, height: 64 } as any;
        lay.spacingX = 6; lay.spacingY = 6;
        lay.paddingTop = 10; lay.paddingLeft = 10;
        gridContainer.setPosition(0, 0);
        invPanel.addChild(gridContainer);

        (panel as any).__equip = eqPanel;
        (panel as any).__grid = gridContainer;

        this.inventoryPanel = panel;
    }

    private refreshInventory() {
        if (!this.inventoryPanel || !this.inventory) return;
        const grid: Node = (this.inventoryPanel as any).__grid;
        grid.removeAllChildren();
        for (const slot of this.inventory.slots) {
            const def = ItemDB[slot.itemId];
            if (!def) continue;
            const cell = makePanel('Cell', 60, 60, hexToColor(RarityColor[def.rarity], 60));
            const icon = makeLabel(def.icon ?? '?', 26);
            icon.setPosition(0, 6);
            cell.addChild(icon);
            const count = makeLabel(slot.count > 1 ? `x${slot.count}` : '', 11);
            count.setPosition(20, -22);
            cell.addChild(count);
            const name = makeLabel(def.name, 9, hexToColor(RarityColor[def.rarity]));
            name.setPosition(0, -18);
            cell.addChild(name);
            cell.addComponent(Button).transition = Button.Transition.SCALE;
            cell.on(Node.EventType.TOUCH_END, () => {
                if (def.kind === 'equipment') this.inventory!.equip(def.id);
                else if (def.kind === 'consumable') this.inventory!.useConsumable(def.id);
                this.refreshInventory();
            });
            grid.addChild(cell);
            this.applyUILayer(cell);
        }
        // Update equipment slots
        const eqPanel: Node = (this.inventoryPanel as any).__equip;
        for (const c of eqPanel.children) {
            const slotKind: EquipSlot | undefined = (c as any).__slotKind;
            if (!slotKind) continue;
            const id = this.inventory.equipment[slotKind];
            const iconLbl: Label | undefined = (c as any).__iconLabel;
            if (!iconLbl) continue;
            if (id) {
                const def = ItemDB[id];
                iconLbl.string = def.icon ?? '?';
                iconLbl.color = hexToColor(RarityColor[def.rarity]);
            } else {
                const defIcons: Record<EquipSlot, string> = { helmet: '⛑️', amulet: '📿', armor: '🛡️', weapon: '⚔️', ring: '💍', boots: '🥾' };
                iconLbl.string = defIcons[slotKind];
                iconLbl.color = new Color(120, 110, 90);
            }
        }
    }

    // ------------- Quest panel -------------
    private buildQuestPanel() {
        const panel = makePanel('QuestPanel', 520, 460, new Color(25, 18, 12, 240));
        anchorCenter(panel);
        panel.active = false;
        this.addToCanvas(panel);

        const titleBar = makePanel('Title', 520, 36, new Color(140, 90, 40));
        titleBar.setPosition(0, 212);
        titleBar.addChild(makeLabel('📜  Quest Log  📜', 18));
        panel.addChild(titleBar);

        const close = makeButton('✕', 30, 28, new Color(160, 50, 50), () => { panel.active = false; });
        close.setPosition(235, 212);
        panel.addChild(close);

        const list = new Node('List');
        list.addComponent(UITransform).setContentSize(490, 400);
        const lay = list.addComponent(Layout);
        lay.type = Layout.Type.VERTICAL;
        lay.resizeMode = Layout.ResizeMode.NONE;
        lay.spacingY = 6;
        lay.paddingTop = 10;
        list.setPosition(0, -20);
        panel.addChild(list);

        (panel as any).__list = list;
        this.questPanel = panel;
    }

    private refreshQuests() {
        if (!this.quests || !this.questPanel) return;
        const list: Node = (this.questPanel as any).__list;
        list.removeAllChildren();
        for (const q of this.quests.quests) {
            if (q.state === 'available' || q.state === 'completed') {
                if (q.state === 'completed') {
                    const row = makePanel('Row', 490, 26, new Color(20, 50, 20, 180));
                    row.addChild(makeLabel(`✓  ${q.title}`, 12, new Color(150, 220, 150)));
                    list.addChild(row);
                    this.applyUILayer(row);
                }
                continue;
            }
            const row = makePanel('Row', 490, 60, new Color(40, 30, 20, 180));
            const titleColor = q.isMain ? new Color(255, 200, 120) : new Color(180, 220, 255);
            const t = makeLabel(`${q.state === 'ready' ? '★ ' : ''}${q.title}`, 13, titleColor);
            t.setPosition(-220, 18); t.getComponent(UITransform)!.anchorX = 0;
            t.getComponent(Label)!.horizontalAlign = Label.HorizontalAlign.LEFT;
            row.addChild(t);

            // objectives
            let lines: string[] = [];
            for (const obj of q.objectives) {
                if (obj.type === 'kill') lines.push(`Kill ${obj.target}: ${obj.current}/${obj.required}`);
                else if (obj.type === 'collect') {
                    const cnt = this.inventory ? this.inventory.countItem(obj.itemId) : 0;
                    const def = ItemDB[obj.itemId];
                    lines.push(`Collect ${def?.name ?? obj.itemId}: ${Math.min(cnt, obj.required)}/${obj.required}`);
                }
            }
            const ot = makeLabel(lines.join('   |   '), 11, new Color(220, 210, 180));
            ot.setPosition(-220, -8);
            ot.getComponent(UITransform)!.anchorX = 0;
            ot.getComponent(Label)!.horizontalAlign = Label.HorizontalAlign.LEFT;
            row.addChild(ot);

            list.addChild(row);
            this.applyUILayer(row);
        }
    }

    // ------------- Dialog -------------
    private buildDialogPanel() {
        const panel = makePanel('Dialog', 720, 240, new Color(20, 15, 10, 240));
        const w = panel.addComponent(Widget);
        w.isAlignHorizontalCenter = true; w.horizontalCenter = 0;
        w.isAlignBottom = true; w.bottom = 130;
        panel.active = false;
        this.addToCanvas(panel);

        const accent = makePanel('Accent', 720, 4, new Color(180, 140, 60));
        accent.setPosition(0, 116); panel.addChild(accent);

        const name = makeLabel('NPC', 16, new Color(255, 220, 130));
        name.setPosition(-330, 90);
        name.getComponent(UITransform)!.anchorX = 0;
        name.getComponent(Label)!.horizontalAlign = Label.HorizontalAlign.LEFT;
        panel.addChild(name);

        const text = makeLabel('...', 14);
        text.setPosition(-330, 50);
        text.getComponent(UITransform)!.setContentSize(660, 80);
        text.getComponent(UITransform)!.anchorX = 0;
        text.getComponent(Label)!.horizontalAlign = Label.HorizontalAlign.LEFT;
        text.getComponent(Label)!.overflow = Label.Overflow.RESIZE_HEIGHT;
        panel.addChild(text);

        const choices = new Node('Choices');
        choices.addComponent(UITransform).setContentSize(700, 90);
        const lay = choices.addComponent(Layout);
        lay.type = Layout.Type.VERTICAL;
        lay.resizeMode = Layout.ResizeMode.NONE;
        lay.spacingY = 4;
        choices.setPosition(0, -50);
        panel.addChild(choices);

        (panel as any).__name = name.getComponent(Label);
        (panel as any).__text = text.getComponent(Label);
        (panel as any).__choices = choices;

        this.dialogPanel = panel;
    }

    private openNpcDialog(npcId: string) {
        const def = NPCDefs.find(n => n.id === npcId);
        if (!def || !this.quests) return;
        const nameLbl: Label = (this.dialogPanel as any).__name;
        const textLbl: Label = (this.dialogPanel as any).__text;
        const choices: Node = (this.dialogPanel as any).__choices;
        nameLbl.string = `${def.name}  (${def.role})`;
        textLbl.string = def.greet;
        choices.removeAllChildren();

        const sets = this.quests.questsForNpc(npcId);
        // Ready -> turn in
        for (const q of sets.ready) {
            const b = makeButton(`★ Turn in: ${q.title}`, 660, 26, new Color(100, 140, 60), () => {
                this.quests!.turnIn(q.id);
                this.openNpcDialog(npcId);
                this.refreshQuests();
            });
            choices.addChild(b);
            this.applyUILayer(b);
        }
        // Available -> accept
        for (const q of sets.available) {
            const b = makeButton(`+ Accept: ${q.title}`, 660, 26, new Color(80, 100, 160), () => {
                this.quests!.accept(q.id);
                this.openNpcDialog(npcId);
                this.refreshQuests();
            });
            choices.addChild(b);
            this.applyUILayer(b);
        }
        // Active -> show status
        for (const q of sets.active) {
            const b = makePanel('Active', 660, 22, new Color(60, 50, 30));
            b.addChild(makeLabel(`… ${q.title}  (in progress)`, 12, new Color(220, 210, 160)));
            choices.addChild(b);
            this.applyUILayer(b);
        }
        if (sets.ready.length + sets.available.length + sets.active.length === 0) {
            const b = makePanel('None', 660, 22, new Color(50, 40, 30));
            b.addChild(makeLabel('— No tasks for you right now —', 12, new Color(180, 170, 140)));
            choices.addChild(b);
            this.applyUILayer(b);
        }
        // Close
        const close = makeButton('Close [ESC]', 660, 24, new Color(100, 60, 60), () => {
            this.dialogPanel.active = false;
            EventBus.emit(GameEvents.DIALOG_CLOSE);
        });
        choices.addChild(close);
        this.applyUILayer(close);

        this.dialogPanel.active = true;
        EventBus.emit(GameEvents.DIALOG_OPEN, npcId);
    }

    // ------------- Help / hint -------------
    private buildHelpHint() {
        const hint = makePanel('Help', 220, 200, new Color(20, 15, 10, 180));
        const w = hint.addComponent(Widget);
        w.isAlignRight = true; w.right = 16;
        w.isAlignBottom = true; w.bottom = 24;
        this.addToCanvas(hint);

        const lines = [
            '— Controls —',
            'WASD : Move',
            'SPACE : Jump / Double Jump',
            'C / L-Shift : Slide',
            'J : Attack',
            'Q E R F : Skills',
            'E / T : Talk to NPC',
            'I : Inventory',
            'L : Quest Log',
            'ESC : Close panels',
        ];
        const t = makeLabel(lines.join('\n'), 11, new Color(220, 200, 160));
        t.setPosition(0, 0);
        t.getComponent(Label)!.horizontalAlign = Label.HorizontalAlign.LEFT;
        t.getComponent(UITransform)!.setContentSize(200, 180);
        hint.addChild(t);
    }

    // ------------- Notifications & popups -------------
    private showNotification(text: string, color = new Color(255, 230, 160)) {
        const n = makePanel('Notif', 300, 28, new Color(30, 20, 10, 220));
        n.addChild(makeLabel(text, 12, color));
        this.notifContainer.addChild(n);
        this.applyUILayer(n);
        const op = n.addComponent(UIOpacity);
        op.opacity = 255;
        this.scheduleOnce(() => {
            // fade out
            const start = Date.now();
            const dur = 600;
            const tick = () => {
                const t = Math.min(1, (Date.now() - start) / dur);
                op.opacity = (1 - t) * 255;
                if (t < 1) requestAnimationFrame(tick);
                else if (n.isValid) n.destroy();
            };
            tick();
        }, 2.4);
    }

    // ------------- Event bindings -------------
    private bindEvents() {
        EventBus.on(GameEvents.PLAYER_STATS_CHANGED, () => this.refreshStats());
        EventBus.on(GameEvents.SKILL_COOLDOWN_CHANGED, (i: number, remaining: number, total: number) => {
            if (i < 0 || i >= 4) return;
            const sb = this.skillButtons[i + 1];
            if (!sb) return;
            const h = (remaining / total) * 60;
            sb.fill.getComponent(UITransform)!.setContentSize(60, h);
            sb.cd.string = remaining > 0.1 ? remaining.toFixed(1) : '';
        });
        EventBus.on(GameEvents.SKILL_USED, (i: number, name: string) => {
            this.showNotification(`✦ ${name}`, new Color(255, 220, 160));
        });
        EventBus.on(GameEvents.PLAYER_LEVEL_UP, (lvl: number) => {
            this.showNotification(`🎉 Level Up!  Lv. ${lvl}`, new Color(255, 220, 100));
        });
        EventBus.on(GameEvents.PLAYER_EXP_GAINED, (amt: number) => {
            this.showNotification(`+${amt} EXP`, new Color(160, 230, 160));
        });
        EventBus.on(GameEvents.ITEM_PICKED_UP, (def: any, count: number) => {
            this.showNotification(`+${count} ${def.icon ?? ''} ${def.name}`, hexToColor(RarityColor[def.rarity as keyof typeof RarityColor]));
        });
        EventBus.on(GameEvents.QUEST_STARTED, (q: any) => {
            this.showNotification(`📜 New Quest: ${q.title}`, new Color(255, 220, 130));
        });
        EventBus.on(GameEvents.QUEST_COMPLETED, (q: any) => {
            this.showNotification(`✅ Completed: ${q.title}`, new Color(150, 230, 150));
        });
        EventBus.on(GameEvents.QUEST_UPDATED, () => this.refreshQuests());
        EventBus.on(GameEvents.ENEMY_DAMAGED, (en: any, dmg: number) => {
            // Boss bar
            if (en?.archetype?.kind === 'boss' && this.bossBar) {
                this.bossBar.panel.active = !en.dead;
                const ratio = Math.max(0, en.hp / en.archetype.maxHP);
                this.bossBar.fill.getComponent(UITransform)!.setContentSize(480 * ratio, 14);
            }
        });
        EventBus.on(GameEvents.ENEMY_DIED, (en: any) => {
            if (en?.archetype?.kind === 'boss' && this.bossBar) this.bossBar.panel.active = false;
            this.showNotification(`💀 Defeated ${en.archetype.name}`, new Color(255, 180, 180));
        });
        EventBus.on(GameEvents.PLAYER_DAMAGED, (dmg: number, hp: number) => {
            // simple screen flash via notification color
        });
        EventBus.on(GameEvents.PLAYER_DIED, () => {
            this.showNotification('☠️  You have fallen...', new Color(255, 80, 80));
            this.scheduleOnce(() => {
                // Respawn at village
                if (this.stats) { this.stats.hp = this.stats.maxHP + this.stats.bonusHP; this.stats.mp = this.stats.maxMP + this.stats.bonusMP; }
                EventBus.emit(GameEvents.PLAYER_STATS_CHANGED, this.stats);
            }, 2);
        });
        EventBus.on(GameEvents.UI_TOGGLE_INVENTORY, () => {
            this.inventoryPanel.active = !this.inventoryPanel.active;
            if (this.inventoryPanel.active) this.refreshInventory();
        });
        EventBus.on(GameEvents.UI_TOGGLE_QUEST, () => {
            this.questPanel.active = !this.questPanel.active;
            if (this.questPanel.active) this.refreshQuests();
        });
        EventBus.on(GameEvents.NPC_INTERACTED, (id: string) => {
            this.openNpcDialog(id);
        });
        EventBus.on(GameEvents.DIALOG_CLOSE, () => { this.dialogPanel.active = false; });
        EventBus.on('npc_in_range', (inRange: boolean) => {
            this.interactHint.active = inRange;
        });
    }

    private refreshStats() {
        if (!this.stats) return;
        const s = this.stats;
        const hpMax = s.maxHP + s.bonusHP;
        const mpMax = s.maxMP + s.bonusMP;
        this.setBar(this.hpBar, s.hp, hpMax);
        this.setBar(this.mpBar, s.mp, mpMax);
        this.setBar(this.stBar, s.stamina, s.maxStamina, false);
        this.setBar(this.xpBar, s.exp, s.expToNext, false);
        this.levelLabel.string = `Lv. ${s.level}`;
        this.goldLabel.string = `💰 ${s.gold}    ⚔ ATK ${s.attack}   🛡 DEF ${s.defense}`;
    }
    private setBar(b: BarRefs, cur: number, max: number, showRatio = true) {
        const r = max > 0 ? cur / max : 0;
        b.fill.getComponent(UITransform)!.setContentSize(b.bgWidth * r, b.fill.getComponent(UITransform)!.contentSize.height);
        b.label.string = `${Math.floor(cur)}/${Math.floor(max)}`;
    }
}

function hexToColor(hex: string, alpha = 255): Color {
    const h = hex.replace('#', '');
    const r = parseInt(h.substr(0, 2), 16);
    const g = parseInt(h.substr(2, 2), 16);
    const b = parseInt(h.substr(4, 2), 16);
    return new Color(r, g, b, alpha);
}